use iced::widget::{svg, Svg};
use iced::Length;

fn icon(data: &'static [u8], size: f32) -> Svg<'static> {
    svg(svg::Handle::from_memory(data))
        .width(Length::Fixed(size))
        .height(Length::Fixed(size))
}

